function validate(input) {
  const [{ Salaries = [] }] = input;
  const seen = new Set(), departments = new Set();
  for (const [name, department, salary] of Salaries) {
    if (name === null || department === null || salary === null) return 'emp_name, department and salary cannot be null.';
    if (department !== 'Engineering' && department !== 'Marketing') return `department must be Engineering or Marketing, not ${department}.`;
    const key = `${name.toLowerCase()}|${department}`;
    if (seen.has(key)) return `(${name}, ${department}) appears twice in Salaries.`;
    if (salary < 0) return 'salary cannot be negative.';
    seen.add(key);
    departments.add(department);
  }
  if (departments.size < 2) return 'Engineering and Marketing each need at least one employee.';
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const departments = ['Engineering', 'Marketing'];
  const Salaries = [];
  if (size === 'small') {
    const names = ['Kathy', 'Roy', 'Jack', 'Evelyn', 'Arthur', 'Terry', 'Anthony', 'Edward'];
    const pay = [30000, 42000, 53000, 61000, 85000, 102000];
    const used = { Engineering: new Set(), Marketing: new Set() };
    const rows = 2 + Math.floor(rand() * 7);
    for (let i = 0; i < rows; i++) {
      // The first two rows put one employee in each department; the rest go anywhere.
      const department = i < 2 ? departments[i] : pick(departments);
      const free = names.filter(name => !used[department].has(name));
      const name = pick(free);
      used[department].add(name);
      Salaries.push([name, department, pick(pay)]);
    }
    // Shuffle so the guaranteed rows are not always first.
    for (let i = Salaries.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Salaries[i], Salaries[j]] = [Salaries[j], Salaries[i]]; }
  } else {
    for (let i = 0; i < 2000; i++) {
      const department = i < 2 ? departments[i] : pick(departments);
      Salaries.push([`Emp${i}`, department, 1000 + Math.floor(rand() * 200000)]);
    }
  }
  return [{ Salaries }];
}
